// Ermittelt Modus (Liste/Detail) und baut die passende Ladequery. Wird sowohl direkt nach dem
// GET-Webhook als auch nach dem POST-Entscheidungs-Schreibvorgang durchlaufen (POST faellt in
// denselben Anzeige-Pfad wie GET, identisches Muster zu Workflow 12).
// $json ist hier "Nav laden (GET)" bzw. "Nav laden (POST-Fallthrough)" (Nav-Call jetzt INLINE
// vor diesem Node, nicht mehr parallel - vermeidet eine n8n-Ausfuehrungsreihenfolge-Race, bei
// der "Baue HTML" den parallelen Nav-Zweig manchmal vor dessen Abschluss per Namens-Lookup
// erreichte). Trigger-Daten deshalb explizit per Namens-Lookup statt aus $json.
// WICHTIG: "POST: SQL ausfuehren" (Postgres-Node) selbst NICHT referenzieren - der ersetzt
// $json durch das rohe Query-Ergebnis (z.B. {"?column?":1} bei einem SELECT 1-Fallback) und
// wuerde mode/recommendation_id klammheimlich verlieren. Der Code-Node DAVOR haelt sie noch.
let fromPost = null;
try { fromPost = $('POST: Entscheidung normalisieren + SQL bauen').first().json; } catch (e) { fromPost = null; }
const isFromPost = fromPost && fromPost.mode === 'detail_nach_post' && fromPost.recommendation_id !== undefined;

let id;
if (isFromPost) {
  id = fromPost.recommendation_id !== null && fromPost.recommendation_id !== undefined ? Number(fromPost.recommendation_id) : null;
} else {
  const trigger = $('Webhook GET (Ansicht)').first().json;
  id = (trigger.query && trigger.query.id) ? Number(trigger.query.id) : null;
}

let sql;
if (id) {
  sql = `SELECT r.id, r.ticker, r.name, r.sektor, r.richtung, r.strategy, r.status,
      r.entry_kurs, r.entry_zone_low, r.entry_zone_high, r.entry_grund, r.trade_thesis,
      r.stop_price, r.target_price, r.reward_risk_ratio,
      r.risk_amount, r.theoretical_quantity, r.position_value, r.position_value_pct,
      r.max_planned_loss, r.estimated_fees, r.estimated_slippage,
      r.expected_holding_days, r.thesis_expires_at,
      r.opportunity_score, r.risk_score, r.evidence_confidence,
      r.market_regime, r.combined_regime, r.market_regime_region,
      r.decision_blockers, r.news_catalyst_json, r.fundamental_quality, r.fundamental_momentum,
      r.valuation_context, r.fundamental_data_quality,
      r.hebelprodukt_typ, r.hebel_spanne, r.basispreis_hebel_3, r.basispreis_hebel_4,
      r.portfolio_risk_before, r.portfolio_risk_after, r.portfolio_blocked_reason,
      r.configuration_snapshot_json, r.risk_model_version, r.thesis_rule_version,
      r.created_at,
      rd.id AS decision_id, rd.entscheidung AS aktuelle_entscheidung, rd.freitext AS aktuelle_freitext,
      rd.ablehnungsgruende_json AS aktuelle_gruende, rd.meine_werte_json AS aktuelle_werte,
      rd.version AS decision_version, rd.entschieden_am,
      pt.trade_id AS paper_trade_id, pt.status AS paper_trade_status,
      pt.simulated_entry_price, pt.exit_price, pt.net_pnl, pt.realized_r_multiple,
      pe.sample_size AS vergleich_sample_size, pe.p_win AS vergleich_p_win,
      pe.expected_value_r AS vergleich_expected_value_r, pe.probability_status AS vergleich_status,
      pe.data_source AS vergleich_quelle
    FROM trading.recommendations r
    LEFT JOIN trading.recommendation_decisions rd ON rd.recommendation_id = r.id AND rd.status = 'aktuell'
    LEFT JOIN trading.paper_trades pt ON pt.recommendation_id = r.id
    LEFT JOIN LATERAL (
      SELECT * FROM trading.probability_estimates pe
      WHERE pe.segment_strategy = r.strategy
        AND pe.segment_direction = r.richtung
        AND pe.segment_market_regime = COALESCE(r.combined_regime, r.market_regime)
        AND pe.probability_status = 'estimated'
        AND (
          (pe.data_source = 'paper_trades'
            AND pe.segment_risk_bucket = (CASE WHEN r.risk_score < 0.33 THEN 'niedrig' WHEN r.risk_score < 0.67 THEN 'mittel' ELSE 'hoch' END)
            AND pe.segment_evidence_bucket = (CASE WHEN r.evidence_confidence < 0.33 THEN 'niedrig' WHEN r.evidence_confidence < 0.67 THEN 'mittel' ELSE 'hoch' END))
          OR
          (pe.data_source = 'simulation_trades'
            AND pe.segment_risk_bucket IS NULL AND pe.segment_evidence_bucket IS NULL)
        )
      -- echte Paper-Trade-Kalibrierung bevorzugen, falls fuers selbe Segment vorhanden, sonst
      -- Simulation-Fallback (Nachtrag Wahrscheinlichkeitskalibrierung-Simulation-v1)
      ORDER BY (pe.data_source = 'paper_trades') DESC
      LIMIT 1
    ) pe ON TRUE
    WHERE r.id = ${id};`;
} else {
  // Liste: nur offene Empfehlungen ohne finale Entscheidung (kein 'angenommen'/'abgelehnt'),
  // sortiert nach Opportunity-Score, hart auf 5 begrenzt (Auftragsvorgabe "0 bis 5 qualitativ
  // gute Kandidaten", keine 30-Aktien-Liste).
  sql = `SELECT r.id, r.ticker, r.name, r.richtung, r.strategy,
      r.opportunity_score, r.risk_score, r.evidence_confidence, r.reward_risk_ratio,
      r.entry_kurs, r.stop_price, r.target_price, r.max_planned_loss,
      rd.entscheidung AS aktuelle_entscheidung
    FROM trading.recommendations r
    LEFT JOIN trading.recommendation_decisions rd ON rd.recommendation_id = r.id AND rd.status = 'aktuell'
    WHERE r.status = 'offen'
      AND (rd.id IS NULL OR rd.entscheidung IN ('beobachten', 'spaeter'))
    ORDER BY r.opportunity_score DESC NULLS LAST
    LIMIT 5;`;
}

return [{ json: { sql, mode: id ? 'detail' : 'liste', id } }];

const rows = $input.all().map(i => i.json).filter(r => r && r.id !== undefined);
const ctx = $('Baue Query (Liste/Detail)').first().json;
let nav = {};
try { nav = $('Nav laden (GET)').first().json; } catch (e1) {
  try { nav = $('Nav laden (POST)').first().json; } catch (e2) { nav = {}; }
}

function esc(s) { return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function fmtNum(v, digits) { return (v === null || v === undefined) ? '-' : Number(v).toFixed(digits === undefined ? 2 : digits); }
function fmtPct(v, digits) { return (v === null || v === undefined) ? '-' : Number(v).toFixed(digits === undefined ? 2 : digits) + '%'; }
function fmtDate(v) {
  if (!v) return '-';
  return new Date(v).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
}
function konfidenzklasse(v) {
  if (v === null || v === undefined) return { label: 'unbekannt', klass: 'muted' };
  const n = Number(v);
  if (n >= 0.67) return { label: 'hoch', klass: 'ok' };
  if (n >= 0.33) return { label: 'mittel', klass: 'warn' };
  return { label: 'niedrig', klass: 'danger' };
}
const RICHTUNG_LABEL = { kauf: 'LONG', verkauf: 'SHORT' };
const ENTSCHEIDUNG_LABEL = {
  angenommen: 'Angenommen (Paper Trade)', abgelehnt: 'Abgelehnt', beobachten: 'Beobachten', spaeter: 'Später entscheiden',
};

const CSS = 'body{font-family:sans-serif;background:#0f1115;color:#e6e6e6;margin:0;padding:32px;max-width:1000px;margin:0 auto;}'
  + 'h1{font-size:22px;color:#fff;margin-bottom:4px;} h2{font-size:15px;color:#fff;margin-top:24px;margin-bottom:8px;}'
  + '.meta{color:#9aa0a6;font-size:13px;margin-bottom:16px;} .hint{color:#9aa0a6;font-size:12px;}'
  + '.card{background:#181b21;border:1px solid #2a2d34;border-radius:8px;padding:16px 20px;margin-bottom:14px;}'
  + '.card h3{margin:0 0 6px 0;font-size:16px;color:#fff;} .card a{color:#8ab4f8;text-decoration:none;}'
  + '.kpi-row{display:flex;gap:16px;flex-wrap:wrap;margin:12px 0;}'
  + '.kpi{background:#1a1c20;padding:10px 16px;border-radius:6px;min-width:110px;}'
  + '.kpi .label{font-size:10px;color:#999;text-transform:uppercase;} .kpi .value{font-size:18px;color:#fff;margin-top:2px;}'
  + '.badge{display:inline-block;padding:2px 8px;border-radius:999px;font-size:11px;font-weight:600;}'
  + '.badge.ok{background:#1c3a2a;color:#6bcf8e;} .badge.warn{background:#3a2c1c;color:#e0a854;}'
  + '.badge.danger{background:#3a1c1c;color:#e0665a;} .badge.muted{background:#22242a;color:#7a7d84;}'
  + 'button{background:#5b8def;border:none;color:#0f1115;font-weight:600;border-radius:6px;padding:8px 16px;font-size:13px;cursor:pointer;margin:4px 6px 4px 0;}'
  + 'button:hover{background:#7ba3f2;} button.danger{background:#e0665a;color:#fff;} button.danger:hover{background:#ef8177;}'
  + 'button.secondary{background:#2a2d34;color:#e6e6e6;} button.secondary:hover{background:#3a3d44;}'
  + 'textarea,input{background:#0f1115;border:1px solid #2a2d34;color:#e6e6e6;border-radius:6px;padding:6px 8px;font-size:13px;box-sizing:border-box;}'
  + 'textarea{width:100%;min-height:60px;margin-top:6px;} label.checkbox{display:inline-flex;align-items:center;gap:4px;font-size:12px;color:#9aa0a6;margin-right:12px;margin-bottom:4px;}'
  + '.werte-anpassen{background:#1a1c20;border:1px solid #2a2d34;border-radius:6px;padding:12px;margin-top:10px;}'
  + '.werte-anpassen .feld{display:inline-block;margin-right:14px;margin-bottom:8px;} .werte-anpassen label{display:block;font-size:11px;color:#9aa0a6;margin-bottom:2px;}'
  + '.pro{color:#6bcf8e;} .contra{color:#e0665a;}';

const NAVBAR_LINKS = '<div style="background:#232323;border:1px solid #444;border-radius:6px;padding:8px 14px;margin-bottom:20px;display:flex;flex-wrap:wrap;gap:4px 16px;font-size:13px;"><a href="/webhook/aktien-status" style="color:#8ab4f8;text-decoration:none;">Status</a></div>';

function pageWrap(title, body) {
  return '<!DOCTYPE html><html lang="de"><head><meta charset="utf-8"><title>' + esc(title) + '</title><style>' + CSS + '</style></head><body>'
    + (nav && nav.navHtml ? nav.navHtml : NAVBAR_LINKS)
    + body
    + '</body></html>';
}

let html;

if (ctx.mode === 'liste') {
  const now = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
  if (rows.length === 0) {
    html = pageWrap('Heute Handeln', ''
      + '<h1>Heute Handeln</h1>'
      + '<div class="meta">Stand: ' + now + '</div>'
      + '<div class="card" style="text-align:center;padding:40px 20px;">'
      + '<h3 style="font-size:24px;">HEUTE KEIN TRADE</h3>'
      + '<div class="hint">Kein Kandidat erfüllt aktuell die Qualitätsschwelle. Das ist ein legitimes Ergebnis, kein Fehler.</div>'
      + '</div>');
  } else {
    const cards = rows.map(r => {
      const konf = konfidenzklasse(r.evidence_confidence);
      const richtungLabel = RICHTUNG_LABEL[r.richtung] || esc(r.richtung);
      return '<div class="card">'
        + '<h3><a href="/webhook/heute-handeln?id=' + esc(r.id) + '">' + esc(r.ticker) + ' - ' + richtungLabel + '</a></h3>'
        + '<div class="hint">' + esc(r.strategy || '') + (r.aktuelle_entscheidung ? ' &middot; bisher: ' + esc(ENTSCHEIDUNG_LABEL[r.aktuelle_entscheidung] || r.aktuelle_entscheidung) : '') + '</div>'
        + '<div class="kpi-row">'
        + '<div class="kpi"><div class="label">Entry</div><div class="value">' + fmtNum(r.entry_kurs) + '</div></div>'
        + '<div class="kpi"><div class="label">Stop</div><div class="value">' + fmtNum(r.stop_price) + '</div></div>'
        + '<div class="kpi"><div class="label">Target</div><div class="value">' + fmtNum(r.target_price) + '</div></div>'
        + '<div class="kpi"><div class="label">CRV</div><div class="value">' + fmtNum(r.reward_risk_ratio) + '</div></div>'
        + '<div class="kpi"><div class="label">Max. Verlust</div><div class="value">' + fmtNum(r.max_planned_loss) + ' EUR</div></div>'
        + '<div class="kpi"><div class="label">Konfidenz</div><div class="value"><span class="badge ' + konf.klass + '">' + konf.label + '</span></div></div>'
        + '</div>'
        + '<a href="/webhook/heute-handeln?id=' + esc(r.id) + '">Vollständiges Entscheidungssheet ansehen &rarr;</a>'
        + '</div>';
    }).join('');
    html = pageWrap('Heute Handeln', ''
      + '<h1>Heute Handeln</h1>'
      + '<div class="meta">Stand: ' + now + ' &middot; ' + rows.length + ' Kandidat(en)</div>'
      + cards);
  }
} else {
  const r = rows[0];
  if (!r) {
    html = pageWrap('Heute Handeln', '<h1>Heute Handeln</h1><div class="card">Empfehlung nicht gefunden. <a href="/webhook/heute-handeln">Zurück zur Liste</a></div>');
  } else {
    const richtungLabel = RICHTUNG_LABEL[r.richtung] || esc(r.richtung);
    const opp = konfidenzklasse(r.opportunity_score);
    const risk = konfidenzklasse(r.risk_score);
    const evid = konfidenzklasse(r.evidence_confidence);

    // Gegenargumente aus decision_blockers (strukturierte Hinweise, siehe docs/HARTE_VETOS.md-Format)
    let blockers = [];
    try { blockers = Array.isArray(r.decision_blockers) ? r.decision_blockers : JSON.parse(r.decision_blockers || '[]'); } catch (e) { blockers = []; }
    const gegenargumenteHtml = blockers.length
      ? '<ul>' + blockers.map(b => '<li class="contra">' + esc(b.message || b.code || JSON.stringify(b)) + '</li>').join('') + '</ul>'
      : '<div class="hint">Keine strukturierten Gegenargumente hinterlegt.</div>';

    // Historische Vergleichsfaelle - ehrlich "keine Stichprobe" statt Scheingenauigkeit
    let vergleichHtml;
    if (r.vergleich_status === 'estimated' && r.vergleich_sample_size) {
      vergleichHtml = '<div class="kpi-row">'
        + '<div class="kpi"><div class="label">Fallzahl</div><div class="value">' + esc(r.vergleich_sample_size) + '</div></div>'
        + '<div class="kpi"><div class="label">Trefferquote</div><div class="value">' + fmtPct((r.vergleich_p_win || 0) * 100) + '</div></div>'
        + '<div class="kpi"><div class="label">Erwartungswert (R)</div><div class="value">' + fmtNum(r.vergleich_expected_value_r) + '</div></div>'
        + '</div><div class="hint">Basis: ' + (r.vergleich_quelle === 'simulation_trades' ? 'Simulationslaeufe' : 'echte Paper Trades') + '.</div>';
    } else {
      vergleichHtml = '<div class="hint">Noch keine ausreichende historische Stichprobe fuer dieses Segment (Strategie/Richtung/Regime/Risiko/Evidenz-Klasse). Keine Schaetzung statt einer erfundenen Zahl.</div>';
    }

    // Portfolio-Auswirkung
    const portfolioHtml = r.portfolio_risk_before !== null
      ? '<div class="hint">Gesamtrisiko vorher: ' + fmtPct(r.portfolio_risk_before) + ' &rarr; nachher: ' + fmtPct(r.portfolio_risk_after) + '</div>'
        + (r.portfolio_blocked_reason ? '<div class="contra">Hinweis: ' + esc(r.portfolio_blocked_reason) + '</div>' : '')
      : '<div class="hint">Noch keine Portfolio-Pruefung durchlaufen.</div>';

    const bereitsEntschieden = r.aktuelle_entscheidung
      ? '<div class="card" style="border-color:#5b8def;"><strong>Deine bisherige Entscheidung:</strong> ' + esc(ENTSCHEIDUNG_LABEL[r.aktuelle_entscheidung] || r.aktuelle_entscheidung)
        + (r.entschieden_am ? ' am ' + fmtDate(r.entschieden_am) : '')
        + (r.aktuelle_freitext ? '<div class="hint">"' + esc(r.aktuelle_freitext) + '"</div>' : '')
        + '</div>'
      : '';

    const hebelHtml = r.hebelprodukt_typ
      ? '<div class="kpi-row">'
        + '<div class="kpi"><div class="label">Produktidee</div><div class="value" style="font-size:13px;">' + esc(r.hebelprodukt_typ) + '</div></div>'
        + '<div class="kpi"><div class="label">Zielhebel</div><div class="value">' + esc(r.hebel_spanne || '-') + '</div></div>'
        + '</div>'
      : '<div class="hint">Keine Hebelprodukt-Empfehlung hinterlegt.</div>';

    const version = r.decision_version !== null && r.decision_version !== undefined ? r.decision_version : '';
    const ABLEHNUNGSGRUENDE = [
      ['risiko_zu_hoch', 'Risiko zu hoch'], ['stop_unlogisch', 'Stop unlogisch'], ['einstieg_gefaellt_nicht', 'Einstieg gefällt nicht'],
      ['news_nicht_ueberzeugend', 'News nicht überzeugend'], ['technik_nicht_ueberzeugend', 'Technik nicht überzeugend'],
      ['portfolio_exponiert', 'Portfolio bereits zu stark exponiert'], ['hebel_zu_hoch', 'Hebel zu hoch'],
      ['ereignisrisiko', 'Ereignisrisiko zu hoch'], ['andere_einschaetzung', 'Ich sehe die Situation anders'], ['sonstiges', 'Sonstiger Grund'],
    ];

    function actionForm(formId, action, buttonLabel, buttonClass, extraFields) {
      return '<form id="' + formId + '" method="POST" action="/webhook/trade-entscheidung">'
        + '<input type="hidden" name="id" value="' + esc(r.id) + '">'
        + '<input type="hidden" name="action" value="' + action + '">'
        + '<input type="hidden" name="version" value="' + esc(version) + '">'
        + (extraFields || '')
        + '</form>'
        + '<button type="submit" form="' + formId + '" class="' + (buttonClass || '') + '">' + buttonLabel + '</button>';
    }

    const ablehnenGruendeHtml = ABLEHNUNGSGRUENDE.map(([code, label]) =>
      '<label class="checkbox"><input type="checkbox" name="ablehnungsgruende" value="' + code + '" form="form-abgelehnt"> ' + esc(label) + '</label>'
    ).join('');

    html = pageWrap(r.ticker + ' - Entscheidungssheet', ''
      + '<a href="/webhook/heute-handeln" class="hint">&larr; Zurück zur Liste</a>'
      + '<h1>' + esc(r.ticker) + ' - ' + richtungLabel + '</h1>'
      + '<div class="meta">' + esc(r.name || '') + ' &middot; Strategie: ' + esc(r.strategy || '-') + ' &middot; erzeugt: ' + fmtDate(r.created_at) + '</div>'
      + bereitsEntschieden

      + '<h2>Setup</h2>'
      + '<div class="kpi-row">'
      + '<div class="kpi"><div class="label">Einstiegszone</div><div class="value">' + fmtNum(r.entry_zone_low) + ' - ' + fmtNum(r.entry_zone_high) + '</div></div>'
      + '<div class="kpi"><div class="label">Stop</div><div class="value">' + fmtNum(r.stop_price) + '</div></div>'
      + '<div class="kpi"><div class="label">Target</div><div class="value">' + fmtNum(r.target_price) + '</div></div>'
      + '<div class="kpi"><div class="label">CRV</div><div class="value">' + fmtNum(r.reward_risk_ratio) + '</div></div>'
      + '<div class="kpi"><div class="label">Erwartete Haltedauer</div><div class="value">' + (r.expected_holding_days ? r.expected_holding_days + ' Tage' : '-') + '</div></div>'
      + '</div>'
      + (r.trade_thesis ? '<div class="hint">These: ' + esc(r.trade_thesis) + '</div>' : '')
      + (r.entry_grund ? '<div class="hint">Entry-Begründung: ' + esc(r.entry_grund) + '</div>' : '')

      + '<h2>Produktidee</h2>' + hebelHtml

      + '<h2>Position &amp; Risiko</h2>'
      + '<div class="kpi-row">'
      + '<div class="kpi"><div class="label">Positionsvorschlag</div><div class="value">' + fmtNum(r.theoretical_quantity, 0) + ' Stück</div></div>'
      + '<div class="kpi"><div class="label">Positionswert</div><div class="value">' + fmtNum(r.position_value) + ' EUR</div></div>'
      + '<div class="kpi"><div class="label">Max. Verlust</div><div class="value">' + fmtNum(r.max_planned_loss) + ' EUR</div></div>'
      + '<div class="kpi"><div class="label">Portfolioanteil</div><div class="value">' + fmtPct(r.position_value_pct) + '</div></div>'
      + '</div>'

      + '<h2>Portfolio-Auswirkung</h2>' + portfolioHtml

      + '<h2>Warum? (Konfidenzklassen statt Scheingenauigkeit)</h2>'
      + '<div class="kpi-row">'
      + '<div class="kpi"><div class="label">Opportunity</div><div class="value"><span class="badge ' + opp.klass + '">' + opp.label + '</span></div></div>'
      + '<div class="kpi"><div class="label">Risiko</div><div class="value"><span class="badge ' + risk.klass + '">' + risk.label + '</span></div></div>'
      + '<div class="kpi"><div class="label">Evidenz-Konfidenz</div><div class="value"><span class="badge ' + evid.klass + '">' + evid.label + '</span></div></div>'
      + '</div>'
      + '<div class="hint">Marktregime: ' + esc(r.combined_regime || r.market_regime || 'unbekannt') + '</div>'

      + '<h2>Gegenargumente</h2>' + gegenargumenteHtml

      + '<h2>Historische Vergleichsfälle</h2>' + vergleichHtml

      + '<h2>Entscheidung</h2>'
      + actionForm('form-angenommen', 'angenommen', 'PAPER TRADE', '')
      + actionForm('form-beobachten', 'beobachten', 'BEOBACHTEN', 'secondary')
      + actionForm('form-spaeter', 'spaeter', 'SPÄTER ENTSCHEIDEN', 'secondary')
      + '<button type="submit" form="form-abgelehnt" class="danger">ABLEHNEN</button>'

      + '<form id="form-abgelehnt" method="POST" action="/webhook/trade-entscheidung">'
      + '<input type="hidden" name="id" value="' + esc(r.id) + '">'
      + '<input type="hidden" name="action" value="abgelehnt">'
      + '<input type="hidden" name="version" value="' + esc(version) + '">'
      + '<div class="werte-anpassen"><div class="hint">Ablehnungsgründe (optional, Mehrfachauswahl):</div>' + ablehnenGruendeHtml
      + '<textarea name="freitext" placeholder="Freitext (optional)" form="form-abgelehnt"></textarea></div>'
      + '</form>'

      + '<h2>Werte anpassen</h2>'
      + '<div class="werte-anpassen">'
      + '<form id="form-werte" method="POST" action="/webhook/trade-entscheidung">'
      + '<input type="hidden" name="id" value="' + esc(r.id) + '">'
      + '<input type="hidden" name="action" value="angenommen">'
      + '<input type="hidden" name="version" value="' + esc(version) + '">'
      + '<div class="feld"><label>Entry-Zone von</label><input name="neu_entry_low" placeholder="' + fmtNum(r.entry_zone_low) + '" form="form-werte"></div>'
      + '<div class="feld"><label>Entry-Zone bis</label><input name="neu_entry_high" placeholder="' + fmtNum(r.entry_zone_high) + '" form="form-werte"></div>'
      + '<div class="feld"><label>Stop</label><input name="neu_stop" placeholder="' + fmtNum(r.stop_price) + '" form="form-werte"></div>'
      + '<div class="feld"><label>Target</label><input name="neu_target" placeholder="' + fmtNum(r.target_price) + '" form="form-werte"></div>'
      + '<div class="feld"><label>Hebel</label><input name="neu_hebel" placeholder="-" form="form-werte"></div>'
      + '<div class="feld"><label>Stückzahl</label><input name="neu_quantity" placeholder="' + fmtNum(r.theoretical_quantity, 0) + '" form="form-werte"></div>'
      + '<textarea name="freitext" placeholder="Begründung der Änderung (optional)" form="form-werte"></textarea>'
      + '<div style="margin-top:8px;"><button type="submit" form="form-werte">Angepasst als Paper Trade annehmen</button></div>'
      + '</form>'
      + '<div class="hint">Leere Felder = Systemvorschlag unverändert übernommen. Der ursprüngliche Vorschlag bleibt in jedem Fall unverändert gespeichert.</div>'
      + '</div>'
    );
  }
}

return [{ json: { html } }];

function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? null : Number(v); }

// FIX-Muster wie Workflow 12 (Fehleranalyse A5): ab hier vertraut der Workflow dem Browser nur
// fuer id/action/freitext/ablehnungsgruende/meine_werte/version - alle inhaltlichen
// Empfehlungsfelder (entry/stop/target/...) werden im naechsten Schritt frisch aus der DB
// geladen, nie aus dem POST-Body uebernommen.
// $json ist hier "Nav laden (POST)" (Nav-Call jetzt INLINE vor diesem Node statt parallel -
// vermeidet eine n8n-Ausfuehrungsreihenfolge-Race, siehe "Baue Query"-Kommentar) - Trigger-Daten
// deshalb per Namens-Lookup statt aus $json.
const trigger = $('Webhook POST (Entscheidung)').first().json;
const j = trigger.body || trigger;
const action = String(j.action || '').trim();
const id = pgNum(j.id);
const freitext = String(j.freitext || '').trim();
const ablehnungsgruende = Array.isArray(j.ablehnungsgruende)
  ? j.ablehnungsgruende
  : (j.ablehnungsgruende ? [j.ablehnungsgruende] : []);
const submittedVersion = pgNum(j.version);

// Werte-Anpassung (Modul 2 "meine Aenderung") - nur uebernehmen, wenn tatsaechlich vom Nutzer
// befuellt (leere Felder = unveraendert). Bleibt separat von system_werte_json, siehe naechster
// Node.
const meineWerteRaw = {
  entry_zone_low: pgNum(j.neu_entry_low),
  entry_zone_high: pgNum(j.neu_entry_high),
  stop_price: pgNum(j.neu_stop),
  target_price: pgNum(j.neu_target),
  hebel: pgNum(j.neu_hebel),
  quantity: pgNum(j.neu_quantity),
};
const meineWerte = {};
for (const [k, v] of Object.entries(meineWerteRaw)) if (v !== null) meineWerte[k] = v;

return {
  json: {
    action, id, freitext, ablehnungsgruende, meine_werte: meineWerte, submittedVersion,
    load_sql: id !== null
      ? `SELECT r.id, r.status, r.entry_kurs, r.entry_zone_low, r.entry_zone_high, r.stop_price,
           r.target_price, r.reward_risk_ratio, r.theoretical_quantity, r.risk_amount, r.hebel_spanne,
           rd.version AS decision_version
         FROM trading.recommendations r
         LEFT JOIN trading.recommendation_decisions rd ON rd.recommendation_id = r.id AND rd.status = 'aktuell'
         WHERE r.id = ${id};`
      : `SELECT NULL::bigint AS id WHERE FALSE;`
  }
};

function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgJsonb(v) { return (v === null || v === undefined) ? "'{}'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }

// Analog Workflow 12: loaded = frisch aus der DB (voriger Node "DB: Empfehlung laden fuer
// Entscheidung"), ctx = die aus dem Body vertrauten Steuerfelder (action/freitext/gruende/
// meine_werte/version). Inhaltliche Werte kommen AUSSCHLIESSLICH aus loaded.
const loaded = $json;
const ctx = $('POST: Baue Load-Query').item.json;
const action = ctx.action;
const id = (loaded && loaded.id !== undefined && loaded.id !== null) ? Number(loaded.id) : null;

const VALID_ACTIONS = new Set(['angenommen', 'abgelehnt', 'beobachten', 'spaeter']);

// Optimistisches Locking (wie Workflow 12, Fehleranalyse A10): submittedVersion ist ein reines
// Konkurrenz-Token gegen die aktuelle Entscheidungsversion (NULL, falls noch keine Entscheidung
// existiert) - kein Inhaltswert.
const currentVersion = loaded && loaded.decision_version !== undefined ? loaded.decision_version : null;
const versionMismatch = ctx.submittedVersion !== null && ctx.submittedVersion !== undefined
  && Number(ctx.submittedVersion) !== (currentVersion === null ? 0 : Number(currentVersion));

let sql;
if (id === null || !VALID_ACTIONS.has(action) || !loaded || loaded.status !== 'offen' || versionMismatch) {
  // Kein passende offene Empfehlung gefunden, ungueltige Aktion, oder zwischenzeitlich bereits
  // anders entschieden (versionMismatch) - egal was der Body behauptet.
  sql = 'SELECT 1;';
} else {
  // EINGEFRORENER Snapshot des Systemvorschlags zum Entscheidungszeitpunkt - wird nach diesem
  // INSERT nie wieder angefasst (siehe HUMAN_IN_THE_LOOP_ARCHITECTURE.md Abschnitt 3.1/7).
  const systemWerte = {
    entry_kurs: loaded.entry_kurs, entry_zone_low: loaded.entry_zone_low, entry_zone_high: loaded.entry_zone_high,
    stop_price: loaded.stop_price, target_price: loaded.target_price, reward_risk_ratio: loaded.reward_risk_ratio,
    theoretical_quantity: loaded.theoretical_quantity, risk_amount: loaded.risk_amount, hebel_spanne: loaded.hebel_spanne,
  };
  const meineWerteJson = ctx.meine_werte && Object.keys(ctx.meine_werte).length > 0 ? ctx.meine_werte : null;

  // Wie trading.strategy_regime_matrix (sql/067): alte "aktuelle" Zeile wird nie ueberschrieben,
  // sondern auf 'ueberholt' gesetzt, neue Zeile eingefuegt - volle Entscheidungshistorie bleibt
  // erhalten, auch wenn der Nutzer seine Meinung mehrfach aendert.
  sql = `UPDATE trading.recommendation_decisions SET status = 'ueberholt'
      WHERE recommendation_id = ${id} AND status = 'aktuell';
    INSERT INTO trading.recommendation_decisions
      (recommendation_id, entscheidung, ablehnungsgruende_json, freitext, system_werte_json, meine_werte_json, entschieden_von)
      VALUES (${id}, ${pgStr(action)}, ${pgJsonb(ctx.ablehnungsgruende)}, ${pgStr(ctx.freitext || null)}, ${pgJsonb(systemWerte)}, ${meineWerteJson ? pgJsonb(meineWerteJson) : 'NULL'}, 'nutzer');`;
}

return [{ json: { sql, mode: 'detail_nach_post', recommendation_id: id } }];
